def _feistel_round(right: int, key: int) -> int:
    material = right.to_bytes(INPUT_BYTES // 2, "big") + key.to_bytes(8, "big")
    digest = hashlib.sha256(b"KMACTF-2026-route-perm|" + material).digest()
    return int.from_bytes(digest[:INPUT_BYTES // 2], "big")


def _input_permutation(value: int) -> int:
    left = value >> FEISTEL_HALF_BITS
    right = value & FEISTEL_HALF_MASK
    for key in FEISTEL_KEYS:
        left, right = right, (left ^ _feistel_round(right, key)) & FEISTEL_HALF_MASK
    return (left << FEISTEL_HALF_BITS) | right


def _projective_normalize(vector: FieldVector) -> FieldVector:
    entries = tuple(component % FIELD_MODULUS for component in vector)
    for component in entries:
        if component != 0:
            scale = pow(component, -1, FIELD_MODULUS)
            return tuple((entry * scale) % FIELD_MODULUS for entry in entries)  # type: ignore[return-value]
    raise ValueError("invalid route value")


def _apply_linear_operator(vector: FieldVector, position: int, symbol: int) -> FieldVector:
    operator = STEP_OPERATORS[position][symbol]
    return tuple(
        sum(vector[column] * operator[row * 4 + column] for column in range(4)) % FIELD_MODULUS
        for row in range(4)
    )  # type: ignore[return-value]


def _evaluate_walk(value: int) -> FieldVector:
    if not (0 <= value < MESSAGE_MAX):
        raise ValueError("invalid route value")

    value = _input_permutation(value)
    symbol = value % ALPHABET_SIZE
    value //= ALPHABET_SIZE

    vector = _apply_linear_operator(INITIAL_VECTOR, 0, symbol)
    for position in range(1, WALK_LENGTH):
        digit = value % BRANCHING_FACTOR
        value //= BRANCHING_FACTOR
        symbol = TRANSITION_TABLE[position - 1][symbol][digit]
        vector = _apply_linear_operator(vector, position, symbol)

    if value:
        raise ValueError("invalid route value")
    return _projective_normalize(vector)


def _pack_vector(vector: FieldVector) -> bytes:
    return b"".join(component.to_bytes(FIELD_BYTES, "big") for component in vector)


def route_digest(value: int) -> bytes:
    material = _pack_vector(_evaluate_walk(value))
    return hashlib.sha256(DOMAIN_SEPARATOR + material).digest()[:DIGEST_BYTES]


def device_route_digest(device_id: int) -> bytes:
    return route_digest(device_id)


def route_bytes(data: bytes) -> bytes:
    if len(data) != INPUT_BYTES:
        raise ValueError(f"expected {INPUT_BYTES} bytes")
    return device_route_digest(int.from_bytes(data, "big"))


def hash_function(device_id: int) -> bytes:
    return device_route_digest(device_id)


def self_test() -> None:
    sample = int.from_bytes(hashlib.sha256(b"device-path-self-test").digest()[:INPUT_BYTES], "big")
    if route_digest(sample) != route_bytes(sample.to_bytes(INPUT_BYTES, "big")):
        raise RuntimeError("route input mismatch")
